def _request_api_key_token(request: Any) -> Optional[str]:
    """Return any sk-unsloth bearer used for authentication, including workflow keys."""
    try:
        header = request.headers.get("authorization")
    except Exception:
        return None
    if not isinstance(header, str):
        return None
    scheme, _, token = header.partition(" ")
    if scheme.lower() != "bearer" or not token.startswith(API_KEY_PREFIX):
        return None
    return token


def _request_has_api_key(request: Any) -> bool:
    """Keyless callers count too: they send no session, so saved-credential rules apply to them as well."""
    if _request_api_key_token(request) is not None:
        return True
    from auth.authentication import admitted_without_session

    return admitted_without_session(request)


def _request_is_internal_workflow(request: Any) -> bool:
    """Matched against stored internal-key hashes, never a prefix, and fails closed on a storage error."""
    token = _request_api_key_token(request)
    if token is None:
        return False
    try:
        return bool(auth_storage.is_internal_api_key(token))
    except Exception:
        logger.debug("external_provider.internal_key_probe_failed", exc_info = True)
        return False


def _request_is_saved_credential_workflow(request: Any) -> bool:
    """Only the Deep Research key may spend a saved provider credential; other internal keys may not."""
    if not _request_is_internal_workflow(request):
        return False
    token = _request_api_key_token(request)
    if token is None:
        return False
    try:
        name = auth_storage.internal_api_key_name(token)
    except Exception:
        logger.debug("external_provider.workflow_key_name_probe_failed", exc_info = True)
        return False
    return name == auth_storage.DEEP_RESEARCH_WORKFLOW_KEY_NAME


def _request_used_api_key(request: Any) -> bool:
    """Third-party sk-unsloth keys only; internal workflow keys are excluded so the API monitor
    stays shut."""
    # Must never fail a load; indeterminate key origin must not count as an external caller.
    # Not for authorization: saved-secret checks use _request_has_api_key.

    # Durable run requests carry no credentials; use the origin recorded at creation.
    recorded = getattr(getattr(request, "state", None), "api_monitor_via_api_key", None)
    if isinstance(recorded, bool):
        return recorded
    token = _request_api_key_token(request)
    if token is None:
        from auth.authentication import admitted_without_session
        return admitted_without_session(request)
    try:
        return not auth_storage.is_internal_api_key(token)
    except Exception:
        logger.debug("api_monitor.internal_key_probe_failed", exc_info = True)
        return False


